def median(values):
    """Return the median of a non-empty list of numbers."""
    s = sorted(values)
    n = len(s)
    if n % 2 == 1:
        return s[n // 2]
    # even-length list: average the two middle values
    return (s[n // 2] + s[n // 2 + 1]) / 2


def mean(values):
    return sum(values) / len(values)

